}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int depositCount = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                depositCount++;
                dfs(grid, visited, i, j);
            }
        }
    }

    return depositCount;
}

private static void dfs(char[][] grid, boolean[][] visited, int row, int col) {
    int[] rowDirections = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] colDirections = {-1, 0, 1, -1, 1, -1, 0, 1};

    visited[row][col] = true;

    for (int d = 0; d < 8; d++) {
        int newRow = row + rowDirections[d];
        int newCol = col + colDirections[d];

        if (newRow >= 0 && newRow < grid.length && newCol >= 0 && newCol < grid[0].length
                && grid[newRow][newCol] == '@' && !visited[newRow][newCol]) {
            dfs(grid, visited, newRow, newCol);
        }
    }
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                count++;
                markDeposit(grid, i, j);
            }
        }
    }
    return count;
}

private static void markDeposit(char[][] grid, int row, int col) {
    if (row < 0 || col < 0 || row >= grid.length || col >= grid[row].length || grid[row][col] != '@') {
        return;
    }
    grid[row][col] = '*';
    markDeposit(grid, row - 1, col); // up
    markDeposit(grid, row + 1, col); // down
    markDeposit(grid, row, col - 1); // left
    markDeposit(grid, row, col + 1); // right
    markDeposit(grid, row - 1, col - 1); // up-left
    markDeposit(grid, row - 1, col + 1); // up-right
    markDeposit(grid, row + 1, col - 1); // down-left
    markDeposit(grid, row + 1, col + 1); // down-right
}

