public static int maxRegions(int N) {
    if (N == 0) return 1;
    int regions = 2; // Starting with one triangle
    for (int i = 2; i <= N; i++) {
        regions += i * (i - 1) / 2 + 1;
    }
    return regions;
}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;
    int regions = 2;
    for (int i = 1; i <= N; i++) {
        regions += 3 * i;
    }
    return regions;
}

public static int maxRegions(int N) {
    if (N == 0) return 1; // Base case: no triangles, 1 region (the whole plane)
    return maxRegions(N - 1) + 2 * N;
}

public static int maxRegions(int N) {
    if (N == 0) return 1; // No triangles, one region (the whole plane)
    if (N == 1) return 2; // One triangle, two regions

    // General formula for the maximum number of regions created by N triangles
    // Starting from N = 2, each new triangle can intersect all previous triangles
    // in up to 6 new points, thus adding at most 7 new regions.
    int regions = 2; // Starting with 1 triangle
    for (int i = 2; i <= N; i++) {
        regions += 7 * (i - 1);
    }
    return regions;
}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    return 2 + N * (N + 1) / 2;
}

