public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create an adjacency list to represent the graph
    List<Integer>[] graph = new List[n * n];
    for (int i = 0; i < n * n; i++) {
        graph[i] = new ArrayList<>();
    }

    // Populate the adjacency list with the given paths
    for (int[] path : paths) {
        int from = path[0] * n + path[1];
        int to = path[2] * n + path[3];
        graph[from].add(to);
        graph[to].add(from);
    }

    // Use a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n * n];
    int startNode = start[0] * n + start[1];
    int endNode = end[0] * n + end[1];

    queue.add(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
        int currentNode = queue.poll();
        if (currentNode == endNode) {
            return "can be travelled";
        }
        for (int neighbor : graph[currentNode]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return canTravel(n, start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int x, int y, int ex, int ey, int[][] paths, boolean[][] visited) {
    if (x == ex && y == ey) {
        return true;
    }
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        if (path[0] == x && path[1] == y) {
            if (canTravel(n, x + path[2], y + path[3], ex, ey, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

