}

private static boolean canTravelMazeHelper(int x, int y, int ex, int ey, boolean[][] visited, int[][] paths) {
    if (x == ex && y == ey) {
        return true;
    }
    if (x < 0 || x >= visited.length || y < 0 || y >= visited[0].length || visited[x][y]) {
        return false;
    }
    visited[x][y] = true;

    for (int[] path : paths) {
        int nx = x + path[0];
        int ny = y + path[1];
        if (canTravelMazeHelper(nx, ny, ex, ey, visited, paths)) {
            return true;
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return canTravelRecursive(start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelRecursive(int startX, int startY, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (startX < 0 || startY < 0 || startX >= visited.length || startY >= visited[0].length || visited[startX][startY]) {
        return false;
    }
    if (startX == endX && startY == endY) {
        return true;
    }
    visited[startX][startY] = true;

    for (int[] path : paths) {
        int nextX = startX + path[0];
        int nextY = startY + path[1];
        if (canTravelRecursive(nextX, nextY, endX, endY, paths, visited)) {
            return true;
        }
    }
    visited[startX][startY] = false; // backtrack
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return canTravelMazeUtil(paths, start[0], start[1], end[0], end[1], visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelMazeUtil(int[][] paths, int currentX, int currentY, int endX, int endY, boolean[][] visited) {
    if (currentX == endX && currentY == endY) {
        return true;
    }
    if (currentX < 0 || currentX >= paths.length || currentY < 0 || currentY >= paths/currentX].length || visited[currentX][currentY] || paths[currentX][currentY] == 0) {
        return false;
    }
    visited[currentX][currentY] = true;
    if (canTravelMazeUtil(paths, currentX + 1, currentY, endX, endY, visited)) return true;
    if (canTravelMazeUtil(paths, currentX - 1, currentY, endX, endY, visited)) return true;
    if (canTravelMazeUtil(paths, currentX, currentY + 1, endX, endY, visited)) return true;
    if (canTravelMazeUtil(paths, currentX, currentY - 1, endX, endY, visited)) return true;
    return false;
}

public static String appx(String word1, String word2) {
    int commonCount = 0;
    boolean[] used = new boolean[word2.length()];

    for (char c : word1.toCharArray()) {
        for (int i = 0; i < word2.length(); i++) {
            if (c == word2.charAt(i) && !used[i]) {
                commonCount++;
                used[i] = true;
                break;
            }
        }
    }

    int totalLength = word1.length() + word2.length();
    int gcd = gcd(commonCount, totalLength);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (totalLength / gcd);
}

