        remainderCount[remainder]++;
    }

    // There must be even count of numbers with remainder 0
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // For every other remainder i, there should be equal number of numbers with remainder k-i
    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }

    return true;
}

