public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int k = 1; k <= n / 2; k++) {
        for (int i = n - 1; i >= k; i--) {
            for (int j = 0; j <= sum; j++) {
                dp[k][i][j] = dp[k][i + 1][j];
                if (j >= nums[i]) {
                    dp[k][i][j] |= dp[k - 1][i + 1][j - nums[i]];
                }
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if (sum * k % n == 0 && dp[k][0][sum * k / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0, n = nums.length;
    for (int num : nums) sum += num;

    boolean[][] possible = new boolean[n / 2 + 1][sum + 1];
    possible[0][0] = true;

    for (int num : nums) {
        for (int i = n / 2; i >= 1; i--) {
            for (int j = 0; j <= sum - num; j++) {
                if (possible[i - 1][j]) {
                    possible[i][j + num] = true;
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && possible[i][sum * i / n]) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int n = nums.length;
    boolean[][][] dp = new boolean[n / 2 + 1][totalSum + 1][n + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int s = num; s <= totalSum; s++) {
                dp[j][s][i] = dp[j][s][i - 1] || dp[j - 1][s - num][i - 1];
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (totalSum * j % n == 0) {
            int s = totalSum * j / n;
            if (dp[j][s][n]) {
                return true;
            }
        }
    }
    return false;
}

