public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) return false; // Early exit if s is too short

    Set<Integer> codes = new HashSet<>();
    int allOnes = (1 << k) - 1;
    int hash = 0;

    for (int i = 0; i < s.length(); i++) {
        hash = ((hash & allOnes) << 1) + (s.charAt(i) - '0');
        if (i >= k - 1) {
            codes.add(hash);
        }
    }

    return codes.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) return false;
    Set<Integer> seen = new HashSet<>();
    int hash = 0;
    for (int i = 0; i < s.length(); i++) {
        hash = (hash << 1) & ((1 << k) - 1) | (s.charAt(i) - '0');
        if (i >= k - 1) seen.add(hash);
    }
    return seen.size() == 1 << k;
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<String> seen = new HashSet<>();

    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);
        if (seen.size() == (1 << k)) {
            return true;
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    int need = 1 << k; // Total number of binary codes of length k
    int[] seen = new int[need]; // Array to mark seen codes
    int allOne = need - 1; // Binary number with k ones
    int hashVal = 0;

    for (int i = 0; i < s.length(); i++) {
        hashVal = ((hashVal & allOne) << 1) + (s.charAt(i) - '0'); // Update hash value for current window
        if (i >= k - 1 && seen[hashVal] == 0) {
            seen[hashVal] = 1; // Mark this code as seen
            need--; // Decrease the count of needed codes
        }
    }

    return need == 0; // Check if all codes are seen
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) {
        return false;
    }
    Set<Integer> found = new HashSet<>();
    int allOnes = (1 << k) - 1;
    int hashVal = 0;
    for (int i = 0; i < s.length(); i++) {
        hashVal = ((hashVal & allOnes) << 1) + (s.charAt(i) - '0');
        if (i >= k - 1) {
            found.add(hashVal);
        }
    }
    return found.size() == (1 << k);
}

