public int minInsertions(String s) {
    int open = 0; // To keep track of open parentheses
    int insertions = 0; // To count the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else {
            // Found a closing parenthesis
            if (open > 0) {
                open--; // Match with an open parenthesis if available
            } else {
                insertions++; // Need to insert an open parenthesis to balance
            }
            // Check the next character if it is also a closing parenthesis
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next closing parenthesis as they form a pair
            } else {
                insertions++; // Need an extra closing parenthesis to balance
            }
        }
    }

    // At the end, we might still have unmatched open parentheses
    insertions += open * 2;

    return insertions;
}

public int minInsertions(String s) {
    int open = 0; // Number of open parentheses needed
    int insertions = 0; // Number of insertions made

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open += 2; // Each '(' needs two ')' to be balanced
            if (open % 2 == 1) {
                insertions++; // Need to insert a ')' to balance an odd open
                open--; // This insertion balances one ')'
            }
        } else {
            open--; // Each ')' closes one open
            if (open == -1) {
                insertions++; // Need to insert a '(' to balance
                open = 1; // This insertion creates one open to be closed
            }
        }
    }

    return insertions + open; // Add remaining open needs
}

public int minInsertions(String s) {
    int left = 0; // unpaired left brackets
    int right = 0; // needed right brackets
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                left++;
                right--;
            }
            right += 2;
        } else {
            right--;
            if (right == -1) {
                left++;
                right = 1;
            }
        }
    }
    return left + right;
}

public int minInsertions(String s) {
    int open = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else {
            if (open > 0) {
                open--;
            } else {
                insertions++;
            }
        }
    }

    // For each remaining open parenthesis, we need two insertions: one for the closing and one if needed to balance pairs
    insertions += 2 * open;
    return insertions;
}

public int minInsertions(String s) {
    int open = 0; // Number of open parentheses needed
    int insertions = 0; // Number of insertions made

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open += 2; // Each '(' needs two ')' to be balanced
            if (open % 2 == 1) {
                // If open is odd, we need to insert a ')' to make it even
                insertions++;
                open--;
            }
        } else {
            open--; // Encountered a ')', so decrease the open count
            if (open == -1) {
                // More ')' than '(' encountered, insert a '('
                insertions++;
                open = 1; // One '(' is needed to balance the current ')'
            }
        }
    }

    return insertions + open; // Add remaining open needs to the insertions
}

