public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    k -= n;
    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int add = Math.min(25, k);
        sb.setCharAt(i, (char) ('a' + add));
        k -= add;
    }
    return sb.toString();
}

