public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    for (int i = 0; i <= 9; i++) {
        if (i >= low) {
            result.add(i);
        }
        findSteppingNumbersHelper(result, i, low, high);
    }

    Collections.sort(result);
    return result;
}

private static void findSteppingNumbersHelper(List<Integer> result, long num, int low, int high) {
    if (num > high) return;

    if (num >= low) {
        result.add((int) num);
    }

    int lastDigit = (int) (num % 10);

    if (lastDigit > 0) {
        findSteppingNumbersHelper(result, num * 10 + (lastDigit - 1), low, high);
    }

    if (lastDigit < 9) {
        findSteppingNumbersHelper(result, num * 10 + (lastDigit + 1), low, high);
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();

        if (num >= low && num <= high) {
            result.add(num);
        }

        if (num > high || num == 0) continue; // Skip further processing if num is out of bounds or zero

        int lastDigit = num % 10;

        if (lastDigit > 0) {
            int nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }

        if (lastDigit < 9) {
            int nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    // Add all single digit numbers to the result if they are within the range
    for (int i = Math.max(0, low); i <= Math.min(9, high); i++) {
        result.add(i);
    }

    Queue<String> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(String.valueOf(i));
    }

    while (!queue.isEmpty()) {
        String numStr = queue.poll();
        int num = Integer.parseInt(numStr);
        if (num > high) continue;
        if (num >= low) result.add(num);

        int lastDigit = num % 10;

        // Construct the next possible stepping numbers
        if (lastDigit > 0) {
            int nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(String.valueOf(nextNum));
            }
        }
        if (lastDigit < 9) {
            int nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(String.valueOf(nextNum));
            }
        }
    }

    // Sort the result list in ascending order
    Collections.sort(result);
    return result;
}

