public static int squarePermutations(int[] A) {
    boolean[] used = new boolean[A.length];
    List<List<Integer>> result = new ArrayList<>();
    backtrack(A, used, new ArrayList<>(), result);
    return result.size();
}

private static void backtrack(int[] A, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == A.length) {
        result.add(new ArrayList<>(current));
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i] || (i > 0 && A[i] == A[i - 1] && !used[i - 1])) continue;

        if (current.isEmpty() || isPerfectSquare(current.get(current.size() - 1) + A[i])) {
            used[i] = true;
            current.add(A[i]);
            backtrack(A, used, current, result);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

private static boolean isPerfectSquare(int n) {
    int root = (int) Math.round(Math.sqrt(n));
    return root * root == n;
}

