public static int squarePermutations(int[] A) {
    int[] count = new int[1000]; // Assuming the values in A are less than 1000
    for (int num : A) {
        count[num]++;
    }

    int result = 0;
    boolean[] used = new boolean[A.length];
    permute(A, 0, -1, count, used, new ArrayList<>(), result);
    return result;
}

private static void permute(int[] A, int index, int last, int[] count, boolean[] used, List<Integer> current, int result) {
    if (index == A.length) {
        result++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (count[A[i]] == 0 || (used[i] && A[i] == A[i - 1])) {
            continue;
        }

        if (last != -1) {
            int sqrt = (int) Math.sqrt(last + A[i]);
            if (sqrt * sqrt != last + A[i]) {
                continue;
            }
        }

        used[i] = true;
        current.add(A[i]);
        count[A[i]]--;

        permute(A, index + 1, A[i], count, used, current, result);

        used[i] = false;
        current.remove(current.size() - 1);
        count[A[i]]++;
    }
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    // Fill left array
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        left[i] = (stack.isEmpty()) ? -1 : stack.peek();
        stack.push(i);
    }

    // Fill right array
    stack = new Stack<>();
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        right[i] = (stack.isEmpty()) ? n : stack.peek();
        stack.push(i);
    }

    // Calculate the maximum area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}

