        left[i] = j;
    }

    // Fill right array with the index of the nearest smaller element on the right side
    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = right[j];
        }
        right[i] = j;
    }

    // Calculate the maximum area
    for (int i = 0; i < n; i++) {
