public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the rightmost digit that is smaller than the digit next to it
    int i;
    for (i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of digits[i] that is greater than digits[i]
    int smallest = i + 1;
    for (int j = i + 2; j < len; j++) {
        if (digits[j] > digits[i] && digits[j] < digits[smallest]) {
            smallest = j;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[smallest];
    digits[smallest] = temp;

    // Sort the digits after the position i
    Arrays.sort(digits, i + 1, len);

    // Convert the array of characters back to an integer
    return Integer.parseInt(new String(digits));
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;

    // Find the first decreasing element from the end
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such element is found, no greater number can be formed
    if (i < 0) {
        return -1;
    }

    // Find the smallest element greater than digits[i] to the right of it
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found elements
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the sequence to the right of the original position of digits[i]
    Arrays.sort(digits, i + 1, digits.length);

    // Convert the character array back to an integer
    long result = Long.parseLong(new String(digits));

    // Check if the result is within the int range
    if (result > Integer.MAX_VALUE) {
        return -1;
    }

    return (int) result;
}

